('advanced-native-1376', '["phrase"]'::jsonb, '{"advanced-native-1376-v1-audio":{"type":"mc","answers":["It matched rooms and group sizes, while people still checked access and confirmed the choices."],"options":["It matched rooms and group sizes, while people still checked access and confirmed the choices.","It confirmed every group’s access needs before the organisers supplied them.","The staff matched the rooms manually and used the tool only to print the final list.","The tool matched rooms by access requirements rather than by group size."]},"advanced-native-1376-v2-reply":{"type":"mc","answers":["The matching work was reduced, so we could focus on needs the tool did not confirm.","It took the heavy lifting off our shoulders by doing the initial room matching.","We no longer had to compare every room size with every group ourselves.","It handled a demanding comparison while leaving the final checks with us."],"options":["The matching work was reduced, so we could focus on needs the tool did not confirm.","It took the heavy lifting off our shoulders by doing the initial room matching.","We no longer had to compare every room size with every group ourselves.","It handled a demanding comparison while leaving the final checks with us."]},"advanced-native-1376-v1-scene":{"type":"mc","answers":["Changing the font helped the presentation, but it did not take the heavy lifting off my shoulders if I still did the demanding checks."],"options":["The helper’s formatting shows that the eligibility checks were transferred to them.","The account says the main difficulty was choosing a readable font rather than checking eligibility.","Changing the font helped the presentation, but it did not take the heavy lifting off my shoulders if I still did the demanding checks."]},"advanced-native-1376-v1-contrast":{"type":"mc","answers":["系統已接手整項任務，人工判斷不再需要。"],"options":["系統可能替我們處理一項費力工作。","系統已接手整項任務，人工判斷不再需要。","仍應確認哪些工作會減少，哪些需要保留。"]},"advanced-native-1376-v1-branch":{"type":"mc","answ