('advanced-native-1377', '["phrase"]'::jsonb, '{"advanced-native-1377-v1-audio":{"type":"mc","answers":["Repeatedly carrying heavy boxes upstairs left the group exhausted."],"options":["The group spent the morning checking box numbers while seated.","The description reports a confirmed back injury caused by the move.","The move was delayed mainly because the archive’s address was unclear.","Repeatedly carrying heavy boxes upstairs left the group exhausted."]},"advanced-native-1377-v2-reply":{"type":"mc","answers":["We had been hauling the boxes upstairs long enough to be worn out by lunch.","The weight and repeated journeys made it much more demanding than checking the labels.","It was back-breaking work carrying heavy boxes up three flights for much of the morning.","The repeated lifting and stair climbing required sustained physical effort."],"options":["We had been hauling the boxes upstairs long enough to be worn out by lunch.","The weight and repeated journeys made it much more demanding than checking the labels.","It was back-breaking work carrying heavy boxes up three flights for much of the morning.","The repeated lifting and stair climbing required sustained physical effort."]},"advanced-native-1377-v1-scene":{"type":"mc","answers":["The account establishes a long wait, but not enough about the effort to justify calling it back-breaking."],"options":["Waiting for many hours establishes the same physical demands as carrying heavy loads.","The account describes repeated lifting rather than waiting for a call.","The account establishes a long wait, but not enough about the effort to justify calling it back-breaking."]},"advanced-native-1377-v1-contrast":{"type":"mc","answers":["有人已由醫生確診背部骨折。"],"options":["有人已由醫生確診背部骨折。","可以追問哪些動作或工作量造成負擔。","說話者把工作形容為非常吃力。"]},"advanced-native-1377-v1-branch":{"type":"mc","answers":["It was back-breaking work because of the weight and repeated stairs; I am describing the effort, not reporting an injury."],"options":["It was back-breaking work because of the weight and repeated stairs; I am describing the effort, not reporting an injury.","I thought the absence of an injury meant the work required little physical effort.","I took the adjective to mean the main problem was boredom rather than exertion."]},"advanced-native-1377-v1-final":{"type":"open","answers":["The worker remembered back-breaking days carrying wet bricks by hand from the yard to the kiln. The weight and repeated journeys explain the effort in this account; it does not record an injury.","Carrying wet bricks to the kiln was back-breaking work, according to the former worker. Each day involved repeated journeys from the yard with loads that had to be moved by hand."],"options":[]}}'::jsonb),
('advanced-native-1378', '["phrase"]'::jsonb, '{"advanced-native-1378-v1-audio":{"type":"mc","answers":["The guide adapted to an unexpected question and distinguished known information from a date needing a check."],"options":["The guide stood up so that the prepared script could be read aloud.","The guide supplied an exact date without mentioning any uncertainty.","The guide adapted to an unexpected question and distinguished known information from a date needing a check.","The visitor asked a rehearsed question that the guide answered from a memorised script."]},"advanced-native-1378-v2-reply":{"type":"mc","answers":["I adapted the answer to the visitor instead of pretending it was in the prepared script.","I explained the available information and left the uncertain point for a check.","I answered from the label and said I would check the uncertain date rather than pretend I knew it.","I had to think on my feet, using the label and admitting that the date needed checking."],"options":["I adapted the answer to the visitor instead of pretending it was in the prepared script.","I explained the available information and left the uncertain point for a check.","I answered from the label and said I would check the uncertain date rather than pretend I knew it.","I had to think on my feet, using the label and admitting that the date needed checking."]},"advanced-native-1378-v1-scene":{"type":"mc","answers":["A fluent prepared speech does not by itself show that he can think on his feet in an unexpected situation."],"options":["The account describes him changing the argument after an unexpected challenge.","The fluency establishes that the speech was composed in response to the audience on the spot.","A fluent prepared speech does not by itself show that he can think on his feet in an unexpected situation."]},"advanced-native-1378-v1-contrast":{"type":"mc","answers":["他必定站着，而且給出的每項資料都已核實。"],"options":["他必定站着，而且給出的每項資料都已核實。","可以再問甚麼變化令他需要應變。","他當時需要迅速作出回應。"]},"advanced-nati